echo ---NOTIFY; docker logs new-api --since 15m 2>&1 | grep -iE "notify" | tail -6; echo ---TOPUP; DB=$(docker ps --format "{{.Names}}" | grep -iE "db|postgres" | head -1); U=$(docker exec $DB env | grep ^POSTGRES_USER= | cut -d= -f2); D=$(docker exec $DB env | grep ^POSTGRES_DB= | cut -d= -f2); docker exec $DB psql -U $U -d $D -tAc "select id, user_id, amount, money, status, create_time, complete_time from top_ups order by id desc limit 3"
